package com.auditlog.api.controller;
import com.auditlog.api.dto.AuditExportBundle; import com.auditlog.api.response.ApiResponse; import com.auditlog.application.service.AuditExportService; import io.swagger.v3.oas.annotations.Operation; import org.slf4j.MDC; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1/audit") public class AuditExportController { private final AuditExportService service; public AuditExportController(AuditExportService service){this.service=service;} @GetMapping("/export") @Operation(summary="Export a verifiable audit bundle",description="Specify exactly one selector. The bundle contains original hash inputs, chain boundaries, and a canonical bundle digest.") public ApiResponse<AuditExportBundle> export(@RequestParam(required=false) String actorId,@RequestParam(required=false) String resourceId){return ApiResponse.success(service.export(actorId,resourceId),MDC.get("traceId"));} }
